import express from 'express';
const app = express();
app.get('/', (req, res) => res.send('Toko Sari buka'));
app.get('/menu', (req, res) => res.json(['Kopi Susu', 'Teh Tarik']));
app.get('/jam-buka', (req, res) => res.status(200).json({ buka: '08:00', tutup: '21:00' }));
const server = app.listen(3000);
const r = await fetch('http://localhost:3000/');
console.log(r.status, await r.text());
const r2 = await fetch('http://localhost:3000/menu');
console.log(await r2.json());
const jam = await (await fetch('http://localhost:3000/jam-buka')).json();
console.log(`${jam.buka} - ${jam.tutup}`);
server.close();

